interface Logger {
  log(msg: string): void
}
class ConsoleLogger implements Logger {
  log(msg: string) { console.log(msg) }
}
class EmptyLogger implements Logger {
  log(msg: string) { /* no-op */ }
}
function getLogger(enabled: boolean): Logger {
  return enabled ? new ConsoleLogger() : new EmptyLogger()
}
const logger = getLogger(false)
logger.log("started")

interface User { name: string; notify(msg: string): void }
class RealUser implements User { constructor(public name: string) {} notify(msg: string) { console.log(msg) } }
class MissingUser implements User { name = 'Guest'; notify(msg: string) { /* ignore */ } }
function findUser(id: number): User { return id > 0 ? new RealUser('Alice') : new MissingUser() }
const user = findUser(0)
user.notify('Welcome')

// Version A: callers check for gateway before each call
interface PaymentGateway { charge(amount: number): boolean }
class RealGateway implements PaymentGateway { charge(a: number) { /* remote call */ return true } }
class OrderService {
  constructor(private gateway: PaymentGateway | null) {}
  place(amount: number) {
    if (this.gateway) {
      this.gateway.charge(amount)
    } else {
      // ignore payment silently
    }
  }
}

// Version B: provide a default implementation so callers do not need checks
class NoopGateway implements PaymentGateway { charge(a: number) { return false } }
class OrderServiceV2 {
  constructor(private gateway: PaymentGateway) {}
  place(amount: number) {
    this.gateway.charge(amount)
  }
}
